        continue
    }

    $state = if (Test-Path $dst) { 'overwrite' } else { 'new' }
    Write-Host ("  {0,-9}  {1}" -f $state, $t)
    $plan += [pscustomobject]@{ Source = $src; Dest = $dst; Name = $t }
}

